-- Backfill only the canonical owner-provided Piraeus wordmark whose repository bytes
-- have been independently verified against the SHA-256 already stored in production.
do $$
declare
  v_content bytea := decode('','base64');
  v_hash text := encode(digest(v_content,'sha256'),'hex');
  v_updated integer;
begin
  if v_hash <> '73fc3353377d38ab00abbb97f2859da0f143595a80bf0f7e3c8b64611632b2ec' then
    raise exception 'PROVIDER_ASSET_HASH_MISMATCH: expected %, got %','73fc3353377d38ab00abbb97f2859da0f143595a80bf0f7e3c8b64611632b2ec',v_hash;
  end if;

  update public.rheomiq_financial_provider_assets
     set content=v_content,
         updated_at=now()
   where asset_key='piraeus-wordmark-green-on-white'
     and provider_id='piraeus'
     and asset_role='wordmark'
     and mime_type='image/jpeg'
     and sha256='73fc3353377d38ab00abbb97f2859da0f143595a80bf0f7e3c8b64611632b2ec';

  get diagnostics v_updated = row_count;
  if v_updated <> 1 then
    raise exception 'PROVIDER_ASSET_BACKFILL_TARGET_MISMATCH: updated % rows',v_updated;
  end if;
end $$;
